 "content": "def transform(grid):
    """Extend colored horizontal bars upward along the vertical marker color."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # A horizontal colored run on a row identifies a bar. The column immediately
    # to its left (or right if needed) carries the color of a vertical guide.
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            color = row[c]
            end = c + 1
            while end < w and row[end] == color:
                end += 1
            # A bar run of length >= 2, with a vertical guide next to its end.
            if end - c >= 2:
                guide_col = None
                for candidate in (c - 1, end):
                    if 0 <= candidate < w and any(grid[rr][candidate] != 0 for rr in range(h) if rr != r):
