 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # A vertical 5-rail carries one or more horizontal motif rows at its end.
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] == 5:
                r += 1
            end = r
            seed_rows = [rr for rr in range(start, end) if c + 1 < w and grid[rr][c + 1] != 0]
            if not seed_rows:
                continue
            # Repeat the motif row(s) along the rail, anchored at its first row.
            patterns = []
            width = 0
            for sr in seed_rows:
                stop = c + 1
                while stop < w and grid[sr][stop] != 0:
                    stop += 1
                pat = grid[sr][c + 1:stop]
                patterns.append(pat)
                width = max(width, len(pat))
            for rr in range(start, end):
                pat = patterns[(rr - start) % len(patterns)]
                for k, value in enumerate(pat, start=c + 1):
                    g[rr][k] = value

    # Rotated case: a horizontal 5-rail carries a vertical motif below it.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] == 5:
                c += 1
            end = c
            # A vertical pattern starts directly below a rail cell; take the
            # contiguous nonzero sequence below the first such seed column.
            seed_col = next((cc for cc in range(start, end)
                             if r + 1 < h and grid[r + 1][cc] not in (0, 5)), None)
            if seed_col is None:
                continue
            stop = r + 1
            while stop < h and grid[stop][seed_col] != 0:
                stop += 1
            pattern = [grid[rr][seed_col] for rr in range(r + 1, stop)]
            for cc in range(start, end):
                for k, value in enumerate(pattern, start=r + 1):
                    g[k][cc] = value
    return g

